    if (byHeaderRgb.has(rgb)) {
      throw new ContentError("BIOMES_INVALID", `duplicate biome header color ${rgb}`, { path });
    }
    byHeaderRgb.set(rgb, biome);
  }
  return { table, byHeaderRgb };
}

