import { createHash } from "node:crypto";
import type { LevelMeta } from "./types.js";
import type { Palette } from "./palette.js";

/** Stable JSON stringify (sorted object keys) for hashing. */
function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map(canonicalJson).join(",")}]`;
  }
  if (typeof value === "object" && value !== null) {
    const entries = Object.entries(value as Record<string, unknown>)
      .filter(([, v]) => v !== undefined)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
      .map(([k, v]) => `${JSON.stringify(k)}:${canonicalJson(v)}`);
    return `{${entries.join(",")}}`;
  }
  return JSON.stringify(value);
}

/**
 * sha256 of map bytes + meta + palette slice (DESIGN §9 `contentHash`).
 * Same bytes → same hash; any meta or palette change → new hash.
 */
export function contentHash(mapPng: Uint8Array, meta: LevelMeta, palette: Palette): string {
  const h = createHash("sha256");
  h.update(mapPng);
  h.update("�meta�");
  h.update(canonicalJson(meta));
  h.update("�palette�");
  h.update(canonicalJson(palette.file));
  return h.digest("hex");
}

