import { describe, expect, it } from "vitest";
import { loadContentRoot, loadLevel, loadMetaFromDir } from "../src/index.js";
import { CONTENT_ROOT } from "./helpers.js";

const index = loadContentRoot(CONTENT_ROOT);

function stripHash<T extends { contentHash: string }>(def: T): Omit<T, "contentHash"> {
  const { contentHash: _contentHash, ...rest } = def;
  return rest;
}

describe("hoard_01 fixture (LVL-01)", () => {
  const def = loadLevel(index, "hoard_01");

  it("parses gold biome with 4 spawns, right-side exit and many treasure slots", () => {
    expect(def.biome).toBe("gold");
    expect(def.spawns).toHaveLength(4);
    expect(def.treasureSlots.length).toBeGreaterThanOrEqual(8);
    expect(def.exit.width).toBeGreaterThan(0);
    // Exit hugs the right side of the room.
    expect(def.exit.x).toBeGreaterThan((def.width * def.blockSizePx) / 2);
    expect(def.musicId).toBe("hoard");
    expect(def.tilesetKey).toBe("tiles_gold");
    expect(def.contentHash).toMatch(/^[0-9a-f]{64}$/);
  });

  it("is excluded from the fork pool", () => {
    const meta = loadMetaFromDir(`${CONTENT_ROOT}/levels/hoard_01`);
    expect(meta.poolEligible).toBe(false);
  });

  it("matches the golden snapshot", () => {
    expect(stripHash(def)).toMatchSnapshot();
  });
});

describe("box_level fixture (LVL-02)", () => {
  const def = loadLevel(index, "box_level");

  it("parses an empty dungeon box with platforms, spawns and exit", () => {
    expect(def.biome).toBe("dungeon");
    expect(def.spawns).toHaveLength(4);
    expect(def.treasureSlots).toHaveLength(0);
    expect(def.exit.height).toBe(2 * def.blockSizePx);
    expect(def.cells[def.height - 1]?.every((c) => c === "brick")).toBe(true);
    expect(def.nearBg).toHaveLength(def.width);
    expect(def.fore).toHaveLength(def.width);
  });

  it("matches the golden snapshot", () => {
    expect(stripHash(def)).toMatchSnapshot();
  });
});

describe("determinism across loads (LVL-21)", () => {
  it("double load produces deep-equal definitions and stable contentHash", () => {
    for (const id of ["hoard_01", "box_level"]) {
      const a = loadLevel(index, id);
      const b = loadLevel(index, id);
      expect(a).toEqual(b);
      expect(a.contentHash).toBe(b.contentHash);
    }
  });
});

import { cpSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, describe, expect, it } from "vitest";
import {
  ContentError,
  loadBiomes,
  loadPalette,
  validateContentRoot,
  validateMeta,
  validatePool,
} from "../src/index.js";
import { C, CONTENT_ROOT, buildPng, makeMeta } from "./helpers.js";

const tmpRoots: string[] = [];
afterAll(() => {
  for (const dir of tmpRoots) rmSync(dir, { recursive: true, force: true });
});

/** Copy the real content pack to a temp dir and corrupt it via `mutate`. */
function corruptedRoot(mutate: (root: string) => void): string {
  const root = mkdtempSync(join(tmpdir(), "dhaul-content-"));
  tmpRoots.push(root);
  cpSync(CONTENT_ROOT, root, { recursive: true });
  mutate(root);
  return root;
}

describe("validateContentRoot on the shipped pack", () => {
  it("passes with zero errors (warnings allowed)", () => {
    const report = validateContentRoot(CONTENT_ROOT);
    expect(report.errors).toEqual([]);
    expect(report.levels).toEqual(["box_level", "hoard_01"]);
  });
});

describe("meta schema (LVL-05, LVL-28)", () => {
  it("fails META_ID_MISMATCH when meta.id differs from folder", () => {
    expect(() => validateMeta(makeMeta({ id: "other" }), "test_level")).toThrowError(
      expect.objectContaining({ code: "META_ID_MISMATCH" }),
    );
  });

  it("fails META_INVALID with stable codes on missing fields", () => {
    for (const bad of [
      { ...makeMeta(), biome: "swamp" },
      { ...makeMeta(), version: undefined },
      { ...makeMeta(), blockSizePx: -1 },
      { ...makeMeta(), displayName: "" },
    ]) {
      try {
        validateMeta(bad, "test_level");
        expect.unreachable("expected META_INVALID");
      } catch (e) {
        expect((e as ContentError).code).toBe("META_INVALID");
      }
    }
  });
});

describe("shared tables", () => {
  it("biomes.json lists all seven biomes (LVL-26)", () => {
    const biomes = loadBiomes(
      JSON.parse(require("node:fs").readFileSync(`${CONTENT_ROOT}/biomes.json`, "utf8")),
    );
    expect(Object.keys(biomes.table).sort()).toEqual(
      ["cavern", "dungeon", "gold", "ice", "lava", "mist", "outside"],
    );
  });

  it("palette rejects unknown semantics and bad hex keys", () => {
    expect(() => loadPalette({ version: 1, colors: { "#123456": "lava_floor" } })).toThrowError(
      expect.objectContaining({ code: "PALETTE_INVALID" }),
    );
    expect(() => loadPalette({ version: 1, colors: { "123456": "brick" } })).toThrowError(
      expect.objectContaining({ code: "PALETTE_INVALID" }),
    );
  });

  it("level-pool.json shape is enforced (LVL-22)", () => {
    expect(validatePool({ version: 1, hoardId: "hoard_01", playablePool: [], levelsAfterHoardDefault: 2 }))
      .toBeTruthy();
    for (const bad of [
      {},
      { version: 1, hoardId: "", playablePool: [], levelsAfterHoardDefault: 2 },
      { version: 1, hoardId: "hoard_01", playablePool: [1], levelsAfterHoardDefault: 2 },
